import{_ as l,l as p,o as e,c as s,v as t,p as i,x as r,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Lamport 时钟","description":"","frontmatter":{"title":"Lamport 时钟","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lamport-clocks.md","filePath":"cs/lamport-clocks.md","lastUpdated":1789023840000}'),h={name:"cs/lamport-clocks.md"};function m(f,a,_,C,u,P){const o=p("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="lamport-时钟" tabindex="-1">Lamport 时钟 <a class="header-anchor" href="#lamport-时钟" aria-label="Permalink to &quot;Lamport 时钟&quot;">​</a></h1><div class="epigraph"><p>没有共享时钟时，「先发生」是消息上的偏序；逻辑时钟给每个事件一个数，使因果不颠倒。</p><footer>—— Lamport, Time, Clocks, and the Ordering of Events in a Distributed System, CACM 1978</footer></div><p><a href="/cs/dijkstra-the">上一课</a>附录对照了共享内存上的互斥。附录对照，不插入主干。主干网络课有报文与<a href="/cs/tcp-handshake">TCP</a>，数据库有<a href="/cs/two-pc">两阶段提交</a>，但没有把「分布式事件序」写成一课。这里对照 <strong>1978 原文的问题</strong>：空间上分开的进程，墙钟不可靠，如何定义因果并给状态机复制一个相容全序。不把 Paxos 插入主干。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dijkstra 的临界区假设共享变量可见。跨主机时，只有消息。墙钟 skew 会把因果说反。Lamport 的缺口是：happened-before 偏序，以及逻辑时钟 \\(C\\) 满足 \\(a\\to b\\Rightarrow C(a)\\lt C(b)\\)。全序广播用时钟加进程号打破并列。主干 2PC 用协调器日志给提交一个全序，是工程特例，不是 1978 文的全部。</p><p><span class="marginnote">逻辑时钟不度量秒。真实时间同步（NTP）是另一问题。向量时钟后来细化并发，1978 文用标量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每进程递增计数器；发送时带上本地时；接收取 max 再加一。由此画事件图。状态机复制：按逻辑时序投递命令，得到相同状态——与数据库「等价串行序」同族，对象是消息而不是读写锁。</p>',8)),(e(),i(c,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HB%5B%22happened-before%22%5D%20--%3E%20LC%5B%22%E9%80%BB%E8%BE%91%E6%97%B6%E9%92%9F%22%5D%0A%20%20LC%20--%3E%20TO%5B%22%E7%9B%B8%E5%AE%B9%E5%85%A8%E5%BA%8F%22%5D%0A%20%20TO%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%202PC%20%2F%20%E6%8A%A5%E6%96%87%E5%BA%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了偏序，才能说「不是因果乱序」与「真正并发」。2PC 的阻塞窗口是故障模型下的原子，不是逻辑时钟的定理。本附录不把拜占庭、Raft 写进 1978。主干刻意不在网络课展开逻辑时钟，以免 TCP 课变成分布式系统课。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>若把 1978 插在 UDP 与 TCP 之间，课序会从字节流跳进状态机复制。主干网络停在传输与应用；分布式序是对照，供已经读完 2PC 的人看提交序与因果序不是同一把尺子。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把这篇与 1974 年 Cerf–Kahn 互联混成「互联网理论」。下一篇才对照分组互联。也不要把逻辑时钟写成区块链入门。</p><p>逻辑时钟不能替代<a href="/cs/two-pc">两阶段提交</a>的投票：因果序不等于原子提交。两者对象不同，附录分篇就是为了不混。</p><p>对照结束应回到主干<a href="/cs/two-pc">两阶段提交</a>的提交序，并分清因果序与原子提交不是同一把尺子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>附录对照，不插入主干。</p></li><li><p>下一篇对照 Cerf–Kahn 1974 分组互联。</p></li><li><p>附录对照 Lamport 1978：因果是消息偏序，逻辑时钟保因果。</p></li><li><p>主干 2PC 给提交全序，不替代 happened-before。</p></li><li><p>不插入 TCP 课序。</p></li><li><p>出处：Lamport, <em>CACM</em> 21(7), 1978。</p></li></ul>',10))])}const E=l(h,[["render",m]]);export{B as __pageData,E as default};
